    iron_glasscaneslicer = { name = "Železni rezalec steklenih palic", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni rezalec steklenih palic za steklarje." },
    bronze_glasscaneslicer = { name = "Bronast rezalec steklenih palic", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast rezalec steklenih palic za steklarje." },
    silver_glasscaneslicer = { name = "Srebrn rezalec steklenih palic", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn rezalec steklenih palic za steklarje." },
    gilded_glasscaneslicer = { name = "Pozlačen rezalec steklenih palic", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen rezalec steklenih palic za steklarje." },
    jewel_set_glasscaneslicer = { name = "Draguljast rezalec steklenih palic", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast rezalec steklenih palic za steklarje." },
    royal_sovereign_glasscaneslicer = { name = "Kraljevski suveren rezalec steklenih palic", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren rezalec steklenih palic z biseri za krono." },
}
local BUILDINGS = {
    glasscaneslicer_workshop = { name = "Glasscaneslicer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
