    master_glasscaneslicer_atelier = { name = "Mojstrski glasscaneslicer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasscaneslicer_palace = { name = "Suverena glasscaneslicer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassCaneSlicerMaker.ironStock=18; GlassCaneSlicerMaker.bronzeStock=14; GlassCaneSlicerMaker.woodStock=10; GlassCaneSlicerMaker.leatherStock=8; GlassCaneSlicerMaker.silverStock=8; GlassCaneSlicerMaker.goldStock=6; GlassCaneSlicerMaker.jewelStock=4; GlassCaneSlicerMaker.pearlStock=4
GlassCaneSlicerMaker.productStock = {}; GlassCaneSlicerMaker.buildings = {}; GlassCaneSlicerMaker.maker = nil; GlassCaneSlicerMaker.activeMaking = {}; GlassCaneSlicerMaker.totalProducts = 0; GlassCaneSlicerMaker.dayTimer = 0
function GlassCaneSlicerMaker.init() GlassCaneSlicerMaker.ironStock=18; GlassCaneSlicerMaker.bronzeStock=14; GlassCaneSlicerMaker.woodStock=10; GlassCaneSlicerMaker.leatherStock=8; GlassCaneSlicerMaker.silverStock=8; GlassCaneSlicerMaker.goldStock=6; GlassCaneSlicerMaker.jewelStock=4; GlassCaneSlicerMaker.pearlStock=4; GlassCaneSlicerMaker.productStock={}; GlassCaneSlicerMaker.buildings={}; GlassCaneSlicerMaker.maker=nil; GlassCaneSlicerMaker.activeMaking={}; GlassCaneSlicerMaker.totalProducts=0; GlassCaneSlicerMaker.dayTimer=0; print("[GlassCaneSlicerMaker] Royal Glass Cane Slicer Maker System initialized (6 products, 4 buildings)") end
function GlassCaneSlicerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassCaneSlicerMaker.maker={name=n or ("Rezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezar najet: %s (spretnost: %d)",GlassCaneSlicerMaker.maker.name,s),"success") end; return true end
function GlassCaneSlicerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassCaneSlicerMaker.build(id) local ok,e=GlassCaneSlicerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassCaneSlicerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassCaneSlicerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassCaneSlicerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassCaneSlicerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassCaneSlicerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassCaneSlicerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassCaneSlicerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassCaneSlicerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassCaneSlicerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassCaneSlicerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassCaneSlicerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassCaneSlicerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassCaneSlicerMaker.buildings==0 then return false,"Potrebna rezna delavnica" end; if not GlassCaneSlicerMaker.maker then return false,"Potreben rezar" end; return true end
function GlassCaneSlicerMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassCaneSlicerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassCaneSlicerMaker.ironStock=GlassCaneSlicerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassCaneSlicerMaker.bronzeStock=GlassCaneSlicerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassCaneSlicerMaker.woodStock=GlassCaneSlicerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassCaneSlicerMaker.leatherStock=GlassCaneSlicerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassCaneSlicerMaker.silverStock=GlassCaneSlicerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassCaneSlicerMaker.goldStock=GlassCaneSlicerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassCaneSlicerMaker.jewelStock=GlassCaneSlicerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassCaneSlicerMaker.pearlStock=GlassCaneSlicerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassCaneSlicerMaker.maker then t=math.max(1,t-math.floor(GlassCaneSlicerMaker.maker.skill/13)) end; table.insert(GlassCaneSlicerMaker.activeMaking,{id="glasscaneslicer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassCaneSlicerMaker.completeMaking(m) local q=1.0+(GlassCaneSlicerMaker.getQualityBonus()/100); if GlassCaneSlicerMaker.maker then q=q+(GlassCaneSlicerMaker.maker.skill/140) end; q=math.min(2.5,q); GlassCaneSlicerMaker.productStock[m.productType]=(GlassCaneSlicerMaker.productStock[m.productType] or 0)+m.quantity; GlassCaneSlicerMaker.totalProducts=GlassCaneSlicerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassCaneSlicerMaker.maker then GlassCaneSlicerMaker.maker.itemsMade=GlassCaneSlicerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassCaneSlicerMaker.maker.skill=math.min(100,GlassCaneSlicerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscaneslicer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassCaneSlicerMaker.update(dt) if not _G.state then return end; GlassCaneSlicerMaker.dayTimer=GlassCaneSlicerMaker.dayTimer+dt; if GlassCaneSlicerMaker.dayTimer>=30 then GlassCaneSlicerMaker.dayTimer=0; for i=#GlassCaneSlicerMaker.activeMaking,1,-1 do local m=GlassCaneSlicerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassCaneSlicerMaker.completeMaking(m); table.remove(GlassCaneSlicerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassCaneSlicerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassCaneSlicerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassCaneSlicerMaker.getStats() return {ironStock=GlassCaneSlicerMaker.ironStock,bronzeStock=GlassCaneSlicerMaker.bronzeStock,woodStock=GlassCaneSlicerMaker.woodStock,leatherStock=GlassCaneSlicerMaker.leatherStock,silverStock=GlassCaneSlicerMaker.silverStock,goldStock=GlassCaneSlicerMaker.goldStock,jewelStock=GlassCaneSlicerMaker.jewelStock,pearlStock=GlassCaneSlicerMaker.pearlStock,productStock=GlassCaneSlicerMaker.productStock,numBuildings=#GlassCaneSlicerMaker.buildings,hasMaker=GlassCaneSlicerMaker.maker~=nil,makerName=GlassCaneSlicerMaker.maker and GlassCaneSlicerMaker.maker.name or "—",makerSkill=GlassCaneSlicerMaker.maker and GlassCaneSlicerMaker.maker.skill or 0,activeMaking=#GlassCaneSlicerMaker.activeMaking,totalProducts=GlassCaneSlicerMaker.totalProducts} end
return GlassCaneSlicerMaker
